-- POC ingestion foundation. Upload batch limits are enforced by the application.
CREATE TABLE "CV_IMPORT_BATCHES" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "TOTAL_FILES" INTEGER NOT NULL,
    "SUCCESS_COUNT" INTEGER NOT NULL DEFAULT 0,
    "FAILED_COUNT" INTEGER NOT NULL DEFAULT 0,
    "STATUS" VARCHAR(20) NOT NULL,
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "COMPLETED_AT" TIMESTAMPTZ,
    CONSTRAINT "PK_CV_IMPORT_BATCHES" PRIMARY KEY ("ID"),
    CONSTRAINT "CK_BATCH_TOTAL_FILES" CHECK ("TOTAL_FILES" > 0),
    CONSTRAINT "CK_BATCH_SUCCESS_COUNT" CHECK ("SUCCESS_COUNT" >= 0),
    CONSTRAINT "CK_BATCH_FAILED_COUNT" CHECK ("FAILED_COUNT" >= 0),
    CONSTRAINT "CK_BATCH_COUNTS" CHECK ("SUCCESS_COUNT"::BIGINT + "FAILED_COUNT"::BIGINT <= "TOTAL_FILES"),
    CONSTRAINT "CK_BATCH_STATUS" CHECK ("STATUS" IN ('PENDING', 'PROCESSING', 'COMPLETED', 'PARTIAL_FAILED', 'FAILED'))
);

CREATE TABLE "CANDIDATES" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "FULL_NAME" VARCHAR(255),
    "EMAIL" VARCHAR(255),
    "PHONE" VARCHAR(50),
    "LOCATION" VARCHAR(255),
    "SUMMARY" TEXT,
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UPDATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_CANDIDATES" PRIMARY KEY ("ID")
);

CREATE TABLE "CV_DOCUMENTS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "BATCH_ID" BIGINT NOT NULL,
    "CANDIDATE_ID" BIGINT,
    "ORIGINAL_FILENAME" VARCHAR(255) NOT NULL,
    "STORAGE_PATH" TEXT NOT NULL,
    "FILE_SIZE" BIGINT NOT NULL,
    "MIME_TYPE" VARCHAR(100) NOT NULL,
    "SHA256" CHAR(64) NOT NULL,
    "STATUS" VARCHAR(20) NOT NULL,
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_CV_DOCUMENTS" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_DOCUMENT_BATCH" FOREIGN KEY ("BATCH_ID") REFERENCES "CV_IMPORT_BATCHES" ("ID"),
    CONSTRAINT "FK_DOCUMENT_CANDIDATE" FOREIGN KEY ("CANDIDATE_ID") REFERENCES "CANDIDATES" ("ID"),
    CONSTRAINT "CK_DOCUMENT_FILE_SIZE" CHECK ("FILE_SIZE" >= 0),
    CONSTRAINT "CK_DOCUMENT_SHA256" CHECK ("SHA256"::TEXT ~ '^[0-9a-f]{64}$'),
    CONSTRAINT "CK_DOCUMENT_STATUS" CHECK ("STATUS" IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED'))
);

CREATE TABLE "CV_PROCESSING_JOBS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "CV_DOCUMENT_ID" BIGINT NOT NULL,
    "STATUS" VARCHAR(20) NOT NULL,
    "RETRY_COUNT" INTEGER NOT NULL DEFAULT 0,
    "ERROR_MESSAGE" TEXT,
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "STARTED_AT" TIMESTAMPTZ,
    "COMPLETED_AT" TIMESTAMPTZ,
    CONSTRAINT "PK_CV_PROCESSING_JOBS" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_JOB_DOCUMENT" FOREIGN KEY ("CV_DOCUMENT_ID") REFERENCES "CV_DOCUMENTS" ("ID"),
    -- Supports the extraction FK that prevents a job/document mismatch.
    CONSTRAINT "UQ_JOB_ID_DOCUMENT" UNIQUE ("ID", "CV_DOCUMENT_ID"),
    CONSTRAINT "CK_JOB_RETRY_COUNT" CHECK ("RETRY_COUNT" >= 0),
    CONSTRAINT "CK_JOB_STATUS" CHECK ("STATUS" IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED'))
);

CREATE TABLE "CV_EXTRACTIONS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "CV_DOCUMENT_ID" BIGINT NOT NULL,
    "PROCESSING_JOB_ID" BIGINT NOT NULL,
    "RAW_TEXT" TEXT,
    "STRUCTURED_DATA" JSONB,
    "EXTRACTION_METHOD" VARCHAR(30) NOT NULL,
    "CREATED_AT" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_CV_EXTRACTIONS" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_EXTRACTION_DOCUMENT" FOREIGN KEY ("CV_DOCUMENT_ID") REFERENCES "CV_DOCUMENTS" ("ID"),
    CONSTRAINT "FK_EXTRACTION_JOB_DOCUMENT" FOREIGN KEY ("PROCESSING_JOB_ID", "CV_DOCUMENT_ID")
        REFERENCES "CV_PROCESSING_JOBS" ("ID", "CV_DOCUMENT_ID"),
    CONSTRAINT "CK_EXTRACTION_METHOD" CHECK ("EXTRACTION_METHOD" IN ('TEXT_EXTRACTION', 'OCR'))
);

CREATE INDEX "IX_DOCUMENT_BATCH" ON "CV_DOCUMENTS" ("BATCH_ID");
CREATE INDEX "IX_DOCUMENT_CANDIDATE" ON "CV_DOCUMENTS" ("CANDIDATE_ID");
CREATE INDEX "IX_DOCUMENT_SHA256" ON "CV_DOCUMENTS" ("SHA256");
CREATE INDEX "IX_JOB_DOCUMENT" ON "CV_PROCESSING_JOBS" ("CV_DOCUMENT_ID");
CREATE INDEX "IX_EXTRACTION_DOCUMENT" ON "CV_EXTRACTIONS" ("CV_DOCUMENT_ID");
CREATE INDEX "IX_EXTRACTION_JOB" ON "CV_EXTRACTIONS" ("PROCESSING_JOB_ID");
